/**
 * Golden vectors for the MMD1 v1 data table (RT95 MM9PDY target).
 *
 * Planner-computed from the MMD1 v1 layout on 2026-10-28 (two independent CRC implementations agree). They
 * were also cross-checked byte for byte against the firmware repo's `fw/tests/vectors/mmd1-v1.json`
 * (retevis-rt95-firmware, generated by `tools/mmd1.py`) on 2026-10-28; cases A-D, the slot edges and the state
 * block agree. Keep these in step with that file if the layout ever gets a new version (new magic, new file).
 *
 * No owner data: the channels below are synthetic.
 */

export interface Mmd1VectorBlock {
  address: number;
  hex: string;
}

export interface Mmd1Vector {
  id: 'A' | 'B' | 'C' | 'D';
  zones: { name: string; channelIndexes: number[] }[];
  descriptions: { channelIndex: number; text: string }[];
  zoneGeneration: number;
  descriptionGeneration: number;
  /** In write order. */
  blocks: Mmd1VectorBlock[];
}

/** Synthetic channels: index 0 (channel 1) and index 2 (channel 3). */
export const MMD1_VECTOR_CHANNELS = [
  { index: 0, slotIndex: 1, rxHz: 146_520_000, wireName: 'TEST01', fingerprint: 0x98 },
  { index: 2, slotIndex: 3, rxHz: 433_500_000, wireName: 'TEST03', fingerprint: 0xac },
] as const;

